import{_ as a,o,c as l,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"图鉴与成就总览","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/atlas.md","filePath":"projects/lotus-plugin/docs/atlas.md"}'),c={name:"projects/lotus-plugin/docs/atlas.md"};function d(i,e,r,s,n,h){return o(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="图鉴与成就总览" tabindex="-1">图鉴与成就总览 <a class="header-anchor" href="#图鉴与成就总览" aria-label="Permalink to &quot;图鉴与成就总览&quot;">​</a></h1><p>返回：<a href="./../README.html">项目主页</a> / <a href="./README.html">文档目录</a></p><p>图鉴数据来自 <code>nanoka-atlas-backend</code>。插件侧负责触发更新、维护本地索引、注册查询指令和渲染图片。</p><h2 id="小功能" tabindex="-1">小功能 <a class="header-anchor" href="#小功能" aria-label="Permalink to &quot;小功能&quot;">​</a></h2><ul><li><a href="./features/atlas-gallery.html">图鉴查询-多游戏资料</a></li><li><a href="./features/achievements.html">成就图鉴-查漏补缺</a></li><li><a href="./features/challenge-query.html">挑战查询-图鉴期数</a></li></ul><h2 id="数据更新" tabindex="-1">数据更新 <a class="header-anchor" href="#数据更新" aria-label="Permalink to &quot;数据更新&quot;">​</a></h2><p>首次使用时，如果本地没有：</p><ul><li><code>data/map.json</code></li><li><code>data/items</code></li><li><code>gallery</code></li></ul><p>会调用后端执行全量抓取。默认只保留简体中文的原神、星铁、绝区零基础资料：角色、武器、套装、成就、邦布、敌人，以及挑战查询依赖的数据页。</p><p>后续更新只增量抓取已保留的数据页；挑战轮换每两小时独立增量刷新一次，不依赖游戏版本变化。挑战期数优先使用源数据的起止时间，避免在月初或版本未更新时停留在上一期。</p><p>更新入口：</p><ul><li><code>#图鉴状态</code></li><li><code>#更新图鉴</code></li><li><code>#检查图鉴更新</code></li><li><code>#全量更新图鉴</code></li><li><code>#重置图鉴</code>：仅清理插件的图鉴缓存；随后执行 <code>#全量更新图鉴</code> 重新初始化。</li></ul><h2 id="查询分流" tabindex="-1">查询分流 <a class="header-anchor" href="#查询分流" aria-label="Permalink to &quot;查询分流&quot;">​</a></h2><p>裸挑战入口不会被图鉴抢占，例如 <code>#深渊</code>、<code>#幻想</code>、<code>#危战</code>、<code>*混沌</code>、<code>*末日</code>、<code>*异相</code>、<code>%防卫战</code> 等仍留给用户挑战数据查询。带“上期/本期/当期/下期”或日期语义时，才按图鉴挑战数据查询。</p><p>成就数据使用本地图鉴的所有原神成就分类。分类名里的中点号可以省略；分类详情会把未完成条目前置，同名多阶段成就按整组排序。</p>',15)])])}const m=a(c,[["render",d]]);export{u as __pageData,m as default};
